resources.afterResponseScript:
insomnia.test('the API is running', () => {
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(insomnia.response.json().message).to.equal('IntraMaps API rodando');
});

insomnia.test('the user is created', () => {
  insomnia.expect(insomnia.response.code).to.equal(201);
  insomnia.expect(insomnia.response.json().username).to.equal(insomnia.environment.get('username'));
});

insomnia.test('login gives a token', () => {
  const body = insomnia.response.json();
  insomnia.environment.set('token', body.token);
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(body.token).to.be.a('string');
});

insomnia.test('the profile is the logged-in user', () => {
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(insomnia.response.json().username).to.equal(insomnia.environment.get('username'));
});

insomnia.test('the gender is updated', () => {
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(insomnia.response.json().gender).to.equal('male');
});

insomnia.test('the floors come with their plan url', () => {
  const floors = insomnia.response.json();
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(floors.length).to.be.at.least(2);
  insomnia.expect(floors[0].plan_url).to.include('/floors/1/plan');
});

insomnia.test('the plan is a PNG image', () => {
  const type = insomnia.response.headers.find((header) => header.key.toLowerCase() === 'content-type');
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(type.value).to.equal('image/png');
});

insomnia.test('the washrooms of floor 1', () => {
  const places = insomnia.response.json();
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(places.length).to.be.above(0);
  insomnia.expect(places.every((place) => place.type === 'washroom' && place.floor_id === 1)).to.equal(true);
});

insomnia.test('the place is room 1001', () => {
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(insomnia.response.json().number).to.equal('1001');
});

insomnia.test('the route goes up to room 2001', () => {
  const route = insomnia.response.json();
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(route.destination.number).to.equal('2001');
  insomnia.expect(route.steps.some((step) => step.changes_floor)).to.equal(true);
});

insomnia.test('one sentence for each step', () => {
  const texts = insomnia.response.json().instructions.map((item) => item.text);
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(texts.length).to.be.above(1);
  insomnia.expect(texts[texts.length - 1]).to.include('2001');
});

insomnia.test('the nearest washroom is for men', () => {
  const route = insomnia.response.json();
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(route.destination.type).to.equal('washroom');
  insomnia.expect(route.destination.gender_restriction).to.equal('male');
});

insomnia.test('the last sentence is the washroom', () => {
  const texts = insomnia.response.json().instructions.map((item) => item.text);
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(texts[texts.length - 1]).to.include('Sanitário');
});

insomnia.test('the favorite is added', () => {
  insomnia.expect(insomnia.response.code).to.equal(204);
});

insomnia.test('the favorite is listed', () => {
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(insomnia.response.json().map((place) => place.id)).to.eql([46]);
});

insomnia.test('the favorite is removed', () => {
  insomnia.expect(insomnia.response.code).to.equal(204);
});

insomnia.test('the two routes are in the history', () => {
  const history = insomnia.response.json();
  insomnia.environment.set('history_id', history[0].id);
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(history.length).to.equal(2);
});

insomnia.test('the item is deleted', () => {
  insomnia.expect(insomnia.response.code).to.equal(204);
});

insomnia.test('the history is cleared', () => {
  insomnia.expect(insomnia.response.code).to.equal(204);
});

insomnia.test('the session is closed', () => {
  insomnia.expect(insomnia.response.code).to.equal(204);
});

insomnia.test('login gives a new token', () => {
  const body = insomnia.response.json();
  insomnia.environment.set('token', body.token);
  insomnia.expect(insomnia.response.code).to.equal(200);
  insomnia.expect(body.token).to.be.a('string');
});

insomnia.test('the account is deleted', () => {
  insomnia.expect(insomnia.response.code).to.equal(204);
});
